   [("FX", "Change"), ("HK$7.8 / US$", "7,8 $HK / $ US"), ("The HK dollar is pegged to the US dollar (band 7.75-7.85)", "Le dollar de Hong Kong est arrimé au dollar US (bande 7,75-7,85)"), ("No currency view needed", "Aucune vue de change nécessaire")],
